import{_ as r,C as i,c as u,o as c,a3 as o,G as n,j as e,a}from"./chunks/framework.Dokpd4od.js";const b=JSON.parse('{"title":"One-step manufacturing","description":"","frontmatter":{},"headers":[],"relativePath":"master/supply-chain/manufacturing/basic-setup/one-step-manufacturing.md","filePath":"master/supply-chain/manufacturing/basic-setup/one-step-manufacturing.md","lastUpdated":1791902625000}'),l={name:"master/supply-chain/manufacturing/basic-setup/one-step-manufacturing.md"};function h(d,t,p,g,m,f){const s=i("ImagePopup");return c(),u("div",null,[t[0]||(t[0]=o('<h1 id="one-step-manufacturing" tabindex="-1">One-step manufacturing <a class="header-anchor" href="#one-step-manufacturing" aria-label="Permalink to &quot;One-step manufacturing&quot;">​</a></h1><p>One-step manufacturing is the simplest way to run production. Components leave your stock location and go straight into production. Finished products come back straight into stock. No extra transfer documents are created, so a small shop can work fast.</p><blockquote><p><strong>In simple words:</strong> Take the parts from stock, build the product, put it back in stock. One document, the manufacturing order.</p></blockquote><p>Open <code>Inventory → Configurations → Warehouse Management → Warehouses</code>, then choose a warehouse and click <strong>Edit</strong>.</p><h2 id="settings" tabindex="-1">Settings <a class="header-anchor" href="#settings" aria-label="Permalink to &quot;Settings&quot;">​</a></h2><p>The <strong>Manufacturing</strong> radio sits in the <strong>Resupply Management</strong> fieldset of the warehouse form. It shows only when the Manufacturing app is installed and <strong>Multi Steps Routes</strong> is on.</p><ol><li>Go to <code>Inventory → Settings → Manage Warehouses</code>.</li><li>Turn on <strong>Multi Steps Routes</strong> and <strong>Locations</strong>.</li><li>Click <strong>Save changes</strong>.</li></ol><p>See <a href="./../../inventories/get-started/inventory-settings.html">Inventory settings</a> and <a href="./../../inventories/warehouses/warehouses.html">Warehouses</a> for the rest of the warehouse form.</p><h2 id="choose-one-step" tabindex="-1">Choose one step <a class="header-anchor" href="#choose-one-step" aria-label="Permalink to &quot;Choose one step&quot;">​</a></h2><ol><li>Open <code>Inventory → Configurations → Warehouse Management → Warehouses</code>.</li><li>Click your warehouse, then the <strong>Edit</strong> tab.</li><li>In <strong>Resupply Management</strong>, select <strong>Manufacture (1 step)</strong> in the <strong>Manufacturing</strong> radio.</li><li>Click <strong>Save changes</strong>.</li></ol>',10)),n(s,{src:"/images1/manufacturing/step1_warehouse_radio.png",alt:"Warehouse Edit form, Resupply Management fieldset, Manufacturing radio with 'Manufacture (1 step)' selected, not yet saved; crop to the fieldset"}),t[1]||(t[1]=o(`<p>The three options are:</p><table tabindex="0"><thead><tr><th>Radio option</th><th>Steps</th><th>Page</th></tr></thead><tbody><tr><td>Manufacture (1 step)</td><td>Manufacture</td><td>This page</td></tr><tr><td>Pick components then manufacture (2 steps)</td><td>Pick, manufacture</td><td><a href="./two-step-manufacturing.html">Two-step manufacturing</a></td></tr><tr><td>Pick components, manufacture, then store products (3 steps)</td><td>Pick, manufacture, store</td><td><a href="./three-step-manufacturing.html">Three-step manufacturing</a></td></tr></tbody></table><h2 id="how-the-stock-moves" tabindex="-1">How the stock moves <a class="header-anchor" href="#how-the-stock-moves" aria-label="Permalink to &quot;How the stock moves&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Stock  ───────────────►  Production  ───────────────►  Stock</span></span>
<span class="line"><span>   components consumed       finished product created</span></span></code></pre></div><p>Production is a virtual location. Components disappear from <strong>Stock</strong> when the order is done. The finished product appears in <strong>Stock</strong> at the same time.</p><h2 id="walk-through-a-manufacturing-order" tabindex="-1">Walk through a manufacturing order <a class="header-anchor" href="#walk-through-a-manufacturing-order" aria-label="Permalink to &quot;Walk through a manufacturing order&quot;">​</a></h2><p>This walk-through uses the same order in all three step pages, so you can compare them. The order is <strong>MO/2</strong>: <strong>Business Laptop</strong>, 2 units, BoM <strong>BOM-MC-LAPTOP</strong>.</p><ol><li>Open <code>Manufacturing → Operations → Manufacturing Orders</code> and click <strong>Create Manufacturing Order</strong>.</li><li>Select <strong>Business Laptop</strong> as <strong>Product</strong> and set <strong>Quantity</strong> to 2. The BoM fills in.</li><li>Click <strong>Create</strong>. The order is in <strong>Draft</strong>.</li><li>Click <strong>Confirm</strong>. The state becomes <strong>Confirmed</strong>.</li></ol>`,8)),n(s,{src:"/images1/manufacturing/step1_mo_confirmed.png",alt:"MO view of a Confirmed order on a 1-step warehouse, header buttons visible; crop to the header and form"}),t[2]||(t[2]=e("ol",{start:"5"},[e("li",null,[a("Open the "),e("strong",null,"Transfers"),a(" sub page. The list is empty, because 1 step creates no pick transfer.")])],-1)),n(s,{src:"/images1/manufacturing/step1_transfers_empty.png",alt:"Transfers sub page of the MO on a 1-step warehouse showing 'No records'"}),t[3]||(t[3]=e("ol",{start:"6"},[e("li",null,[a("Click "),e("strong",null,"Produce All"),a(". The state becomes "),e("strong",null,"Done"),a(".")])],-1)),n(s,{src:"/images1/manufacturing/step1_mo_done.png",alt:"The same MO in Done state; Components tab showing consumed quantities"}),t[4]||(t[4]=o('<h2 id="actions-and-statuses" tabindex="-1">Actions and statuses <a class="header-anchor" href="#actions-and-statuses" aria-label="Permalink to &quot;Actions and statuses&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Moment</th><th>What happens</th></tr></thead><tbody><tr><td><strong>Confirm</strong></td><td>The state becomes <strong>Confirmed</strong>. No transfer is created.</td></tr><tr><td><strong>Produce All</strong></td><td>Components leave <strong>Stock</strong>. The finished product enters <strong>Stock</strong>. State <strong>Done</strong>.</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>Choose one step when the same people pick, build and store. It has the least paperwork.</p></div><h2 id="see-also" tabindex="-1">See also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See also&quot;">​</a></h2><ul><li><a href="./two-step-manufacturing.html">Two-step manufacturing</a></li><li><a href="./three-step-manufacturing.html">Three-step manufacturing</a></li><li><a href="./manufacturing-order-costs.html">Manufacturing order costs</a></li><li><a href="./../../inventories/routes/">Routes</a></li><li><a href="./../workflows/">Manufacturing order lifecycle</a></li></ul>',5))])}const _=r(l,[["render",h]]);export{b as __pageData,_ as default};
